async function p55ProducerFactory(sourceHash) {
const fs=await import("node:fs"),path=await import("node:path"),crypto=await import("node:crypto");
const sha=b=>crypto.createHash("sha256").update(b).digest("hex");
const canon=x=>x===null?"null":typeof x==="bigint"?String(x):typeof x==="number"||typeof x==="boolean"?JSON.stringify(x):typeof x==="string"?JSON.stringify(x):Array.isArray(x)?"["+x.map(canon).join(",")+"]":"{"+Object.keys(x).sort().map(k=>JSON.stringify(k)+":"+canon(x[k])).join(",")+"}";
const encode=x=>Buffer.from(canon(x)+"\n","utf8"),fail=r=>{throw Error(r)};
const fresh=["build/phase16-validation55-bootstrap","build/phase16-validation55-preflight"];
const root=nodeRepl.cwd,resolve=p=>path.join(root,p);
const readStable=p=>{const a=fs.lstatSync(resolve(p),{bigint:true});if(!a.isFile()||!(a.mode&292n))fail("READ_UNAVAILABLE");const b=fs.readFileSync(resolve(p)),z=fs.lstatSync(resolve(p),{bigint:true});for(const k of ["ino","mode","size","mtimeNs"])if(a[k]!==z[k])fail("READ_DRIFT");if(BigInt(b.length)!==a.size)fail("READ_DRIFT");return b;};
let prefix=null,snapshot=null,snapshotMeta=null,table=null,graph=null;
const cursors=new Map(),readBindings=new Map(),cases=new Map(),originals=new Map();
let outputPending=null,publicationCursor=0,journal=null,lastIntent=null,ready=false;
const segment=(b,i,offset)=>({index:i,offset,length:b.length,sha256:sha(b),codec:"base64",encoded_length:4*Math.ceil(b.length/3),data:b.toString("base64")});
const roots=()=>{const names=fs.readdirSync(resolve("build"),{encoding:"utf8"}).filter(n=>n.startsWith("phase16-")).map(n=>"build/"+n).filter(n=>!fresh.includes(n));return names.concat([".planning/phases/16-host-evidence-and-roadmap","AGENTS.md",".planning/PROJECT.md",".planning/ROADMAP.md",".planning/REQUIREMENTS.md",".planning/STATE.md",".planning/config.json","README.md","include/nesturbator.h","tests/retroarch","CMakePresets.json",".github/workflows/ci.yml"]).sort();};
const capture=()=>{if(snapshot)fail("CAPTURE_DUPLICATE");const names=roots(),rows=[],seen=new Set();let hashes=0,metadata=0;
const walk=p=>{if(seen.has(p))return;seen.add(p);const a=fs.lstatSync(resolve(p),{bigint:true});const row={path:p,type:Number(a.mode&61440n),mode:Number(a.mode&4095n),size:a.size,mtime_ns:a.mtimeNs,inode:a.ino};
if(a.isSymbolicLink()){row.target=fs.readlinkSync(resolve(p),{encoding:"utf8"});const z=fs.lstatSync(resolve(p),{bigint:true});if(a.ino!==z.ino||a.mode!==z.mode||a.size!==z.size||a.mtimeNs!==z.mtimeNs)fail("SNAPSHOT_DRIFT");rows.push(row);}
else if(a.isDirectory()){rows.push(row);const children=fs.readdirSync(resolve(p),{encoding:"utf8"}).sort();for(const c of children){if(c.includes("\uFFFD"))fail("SNAPSHOT_UTF8_INVALID");walk(p+"/"+c);}const z=fs.lstatSync(resolve(p),{bigint:true});if(a.ino!==z.ino||a.mode!==z.mode||a.mtimeNs!==z.mtimeNs)fail("SNAPSHOT_DRIFT");}
else if(a.isFile()){if(a.mode&292n){row.sha256=sha(readStable(p));hashes++;}else{row.metadata_only=true;metadata++;}rows.push(row);}else fail("SNAPSHOT_SCHEMA_INVALID");};
for(const r of names)walk(r);rows.sort((a,b)=>a.path<b.path?-1:a.path>b.path?1:0);snapshot=encode(rows);table=[];
for(let off=0,index=0;off<snapshot.length;off+=4096,index++)table.push({index,offset:off,length:Math.min(4096,snapshot.length-off),sha256:sha(snapshot.subarray(off,off+4096))});
snapshotMeta={bytes:snapshot.length,sha256:sha(snapshot),entries:rows.length,raw_hashes:hashes,metadata_only:metadata,segments:table.length,packets:Math.ceil(table.length/2),roots:names};
return snapshotMeta;};
const getPrefix=()=>{if(!prefix){prefix=readStable("build/phase16-validation38-bootstrap/copy-operations.jsonl");if(prefix.length!==13136||sha(prefix)!=="5d9dc44bca2c69a9d4e5ac248ae1d9942c4cafd9ee4e208902b6b87695d9b195")fail("RETAINED_PREFIX_CHANGED");}return prefix;};
const originalFrame=r=>{if(!r||r.isError!==false||!Array.isArray(r.content)||r.content.length!==1||r.content[0].type!=="text")fail("ACTUAL_A_INVALID");const text=r.content[0].text;if(Buffer.byteLength(text)>16384||!text.endsWith("\n"))fail("ACTUAL_A_INVALID");const o=JSON.parse(text);if(canon(o)+"\n"!==text)fail("ACTUAL_A_INVALID");return o;};
const makeGraph=q=>{if(graph)fail("GRAPH_DUPLICATE");if(!snapshotMeta)fail("SNAPSHOT_RECEIPT_MISSING");if(!Array.isArray(q.files)||q.files.length<3||q.files.length>32)fail("GRAPH_SCHEMA_INVALID");
const ops=[{kind:"bootstrap-header",target:fresh[0]}];
for(const f of q.files){if(typeof f.path!=="string"||!f.path.startsWith(fresh[0]+"/")||path.posix.normalize(f.path)!==f.path||f.path.split("/").slice(2).some(x=>x===".."||x==="."||x==="")||(typeof f.data!=="string"&&typeof f.source!=="string"))fail("GRAPH_SCHEMA_INVALID");if(f.source&&(path.posix.normalize(f.source)!==f.source||path.posix.isAbsolute(f.source)||f.source.startsWith("../")))fail("GRAPH_SCOPE_INVALID");const b=f.source?readStable(f.source):Buffer.from(f.data,"base64");if(f.source&&(b.length!==f.bytes||sha(b)!==f.sha256))fail("GRAPH_SOURCE_CHANGED");if(b.length>4194304)fail("TRANSPORT_BOUND_EXCEEDED");ops.push({kind:"file",target:f.path,bytes:b.length,sha256:sha(b),data:b.toString("base64")});}
for(const d of table)ops.push({kind:"snapshot-segment",target:fresh[0]+"/copy-operations.jsonl",segment:d.index,offset:d.offset,bytes:d.length,sha256:d.sha256});
const earlierCount=q.receipt_count+ops.length*2,slotBytes=32768;if(!Number.isSafeInteger(earlierCount)||earlierCount<1)fail("GRAPH_SCHEMA_INVALID");
for(let slot=0;slot<earlierCount;slot++)for(let offset=0;offset<slotBytes;offset+=4096)ops.push({kind:"archive-segment",target:fresh[0]+"/copy-operations.jsonl",slot,offset,bytes:Math.min(4096,slotBytes-offset),cutoff:earlierCount});
ops.push({kind:"seal",target:fresh[0]+"/copy-operations.jsonl",snapshot_sha256:snapshotMeta.sha256,segments:table.length,archive_slots:earlierCount,slot_bytes:slotBytes});
graph={schema:"p55-finite-publication-graph-v1",operations:ops,earlier_count:earlierCount,snapshot:snapshotMeta,files:ops.filter(o=>o.kind==="file").map(o=>({path:o.target,bytes:o.bytes,sha256:o.sha256}))};
return {operations:ops.length,archive_slots:earlierCount,graph_sha256:sha(encode(graph)),graph_bytes:encode(graph).length,graph_packets:Math.ceil(encode(graph).length/8192),snapshot_sha256:snapshotMeta.sha256};};
const execute=q=>{
if(!q||typeof q.case_id!=="string"||q.case_id.length>96||typeof q.op!=="string")fail("REQUEST_INVALID");
if(["PREFIX_READ","SNAPSHOT_READ","SNAPSHOT_COMPARE","GRAPH_READ","GRAPH_COMPARE"].includes(q.op)){
const key=q.op,bytes=key==="PREFIX_READ"?getPrefix():key.startsWith("GRAPH_")?(graph?encode(graph):null):snapshot;if(!bytes)fail("SNAPSHOT_RECEIPT_MISSING");
const count=Math.ceil(bytes.length/8192),cursor=cursors.get(key)||0;if(outputPending||q.index!==cursor||cursor>=count)fail("SNAPSHOT_INDEX_INVALID");
const start=cursor*8192,segments=[];for(let off=start,index=cursor*2;off<Math.min(start+8192,bytes.length);off+=4096,index++)segments.push(segment(bytes.subarray(off,Math.min(off+4096,bytes.length)),index,off));
return {reason:"PACKET_READY",payload:{stream:key,index:cursor,count,total:bytes.length,sha256:sha(bytes),segments},pending:{key,index:cursor}};
}
if(q.op==="ACK"){if(Object.keys(q).some(k=>!["op","case_id","stream","index","frame_sha256","receiver_committed"].includes(k)))fail("ACK_CARRIES_READ");if(!outputPending||q.stream!==outputPending.key||q.index!==outputPending.index||q.frame_sha256!==outputPending.frame_sha256||q.receiver_committed!==true)fail("ACK_BEFORE_COMMIT");const next=q.index+1;cursors.set(q.stream,next);outputPending=null;return {reason:"ACK_ACCEPTED",payload:{stream:q.stream,index:q.index,next}};}
if(q.op==="CAPTURE")return {reason:"SNAPSHOT_CAPTURED",payload:capture()};
if(q.op==="TABLE"){if(!table)fail("SNAPSHOT_RECEIPT_MISSING");const count=Math.ceil(table.length/48);if(!Number.isInteger(q.index)||q.index<0||q.index>=count)fail("SNAPSHOT_INDEX_INVALID");return {reason:"TABLE_READY",payload:{index:q.index,count,total:table.length,rows:table.slice(q.index*48,q.index*48+48)}};}
if(q.op==="GRAPH")return {reason:"GRAPH_PREPARED",payload:makeGraph(q)};
if(q.op==="GRAPH_READ"){if(!graph)fail("GRAPH_MISSING");const b=encode(graph),off=q.index*8192;if(!Number.isInteger(q.index)||q.index<0||off>=b.length)fail("SNAPSHOT_INDEX_INVALID");return {reason:"GRAPH_PACKET_READY",payload:{index:q.index,count:Math.ceil(b.length/8192),total:b.length,sha256:sha(b),data:b.subarray(off,off+8192).toString("base64")}};}
if(q.op==="A"){
