}
if(logical.op==="SNAPSHOT_COMPARE"||logical.op==="GRAPH_COMPARE"){const prior=state.streams[logical.op==="SNAPSHOT_COMPARE"?"SNAPSHOT_READ":"GRAPH_READ"];if(prior.cursor!==prior.count||load(prior.parts[p.index])!==raw)fail("SNAPSHOT_BYTES_MISMATCH");}
