}
if(logical.op==="ACK"){
const s=state.streams[logical.stream],p=f.payload;
if(!s||!s.pending||!s.pending.receiver_committed||logical.receiver_committed!==true)fail("ACK_BEFORE_COMMIT");
if(Object.keys(logical).some(k=>!["op","case_id","stream","index","frame_sha256","receiver_committed"].includes(k)))fail("ACK_CARRIES_READ");
if(logical.index!==s.pending.index||logical.frame_sha256!==s.pending.frame_sha256||p.stream!==logical.stream||p.index!==logical.index||p.next!==s.cursor+1)fail("ACK_CURSOR_INVALID");
