if(P===null||P===undefined||P.length!==p.prefix.bytes||c.sha(P)!==p.prefix.sha256)fail("JOURNAL_PREFIX_INVALID");
if(state.cases[logical.case_id])fail("DUPLICATE_INTENT");
const operation=logical.mode==="durable"?load("p55-graph-op:"+logical.action.index):null;
let content=null;
if(operation?.kind==="snapshot-segment"){const chunks=state.streams.SNAPSHOT_READ.parts.map(k=>load(k)).join("");content=chunks.slice(operation.offset,operation.offset+operation.bytes);}
if(operation?.kind==="archive-segment")content=c.dec(logical.action.data);
