store(key+":request",request);store(key+":binding",frozen);
let original;
try{original=await tools[tool](request);}catch(e){state.terminal=true;store("p55-receiver-state",state);store(key+":rejection",{message:String(e.message)});throw Error("NESTED_REJECTION");}
store(key,original);
const exact=JSON.stringify(original);store(key+":exact",exact);
(state.ledger_keys||(state.ledger_keys=[])).push(key);
originalCount++;
if(load(key)===undefined||load(key+":exact")!==exact)throw Error("ORIGINAL_RETENTION_MISSING");
