state=result.state;
store(key+":receipt",result.receipt);
if(tool==="mcp__node_repl__js")state.producer_initialized=true;
store("p55-receiver-state",state);
return result;
};
try{
if(env.kind==="stream"){
const stream=state.streams[env.stream];if(!stream||stream.pending!==null)throw Error("ACK_REQUIRED");
start=stream.cursor;
for(let n=0;n<env.limit&&stream.cursor<stream.count;n++){
const i=stream.cursor,id=env.case_prefix+"-"+String(i).padStart(6,"0");
const r=await invoke({op:env.stream,case_id:id,index:i},{exit:0,reason:"PACKET_READY"});
const pending=stream.pending;if(!pending||pending.receiver_committed!==true)throw Error("RECEIVER_COMMIT_MISSING");
const readKey="p55-original:"+id+":"+env.stream;if(load(readKey)===undefined||typeof load(readKey+":exact")!=="string")throw Error("ORIGINAL_LOST");
await invoke({op:"ACK",case_id:id+"-ack",stream:env.stream,index:i,frame_sha256:r.receipt.wire_sha256,receiver_committed:true},{exit:0,reason:"ACK_ACCEPTED"});
